function Choice({value,onChange,options,placeholder='Bitte auswählen',label,disabled=false}:{value:string;onChange:(s:string)=>void;options:{id:string;name:string}[];placeholder?:string;label:string;disabled?:boolean}){return <Select value={value} onValueChange={onChange} disabled={disabled}><SelectTrigger className="w-full" aria-label={label}><SelectValue placeholder={placeholder}/></SelectTrigger><SelectContent>{options.map(o=><SelectItem key={o.id} value={o.id}>{o.name}</SelectItem>)}</SelectContent></Select>}
function duration(p:Punch,now:number){const mins=Math.max(0,Math.floor(((p.ended?Date.parse(p.ended):now)-Date.parse(p.started))/60000)-(p.pause??0));return `${Math.floor(mins/60)}:${String(mins%60).padStart(2,'0')} h`}
