function EmployeeReport({data}:{data:Data}){const employees=data.resources.filter(r=>r.kind==='employee');const [employeeId,setEmployeeId]=useState('');const [period,setPeriod]=useState<'week'|'month'>('week');const [anchor,setAnchor]=useState(()=>iso(new Date()));const employee=employees.find(r=>r.id===employeeId);const startDate=new Date(anchor+'T00:00:00');const days=Array.from({length:period==='week'?7:30},(_,i)=>addDays(startDate,i));const hours=(day:string)=>{const a=data.assignments.find(x=>x.resource_id===employeeId&&x.day===day);if(a&&['vacation','unpaid','sick'].includes(a.assignment_type))return 8;const punches=data.punches.filter(p=>p.resource_id===employeeId&&p.started.slice(0,10)===day&&p.ended);return punches.reduce((sum,p)=>sum+Math.max(0,(Date.parse(p.ended!)-Date.parse(p.started))/3600000-(p.pause||0)/60),0)};const [edits,setEdits]=useState<Record<string,string>>({});const value=(d:string)=>edits[d]??hours(d).toFixed(2);function download(){const rows=days.map(d=>`<tr><td>${format(d,'dd.MM.yyyy')}</td><td>${format(d,'EEEE',{locale:de})}</td><td>${value(iso(d))} h</td></tr>`).join('');const html=`<html><head><meta charset="utf-8"><title>Mitarbeiter-Stundennachweis</title><style>body{font-family:Arial;padding:32px;color:#17233a}h1{font-size:22px}table{border-collapse:collapse;width:100%;margin-top:20px}td,th{border:1px solid #b9c4d3;padding:9px;text-align:left}th{background:#edf2f8}.sum{margin-top:18px;font-weight:bold}</style></head><body><h1>Stundennachweis · ${employee?.name||'Mitarbeiter'}</h1><p>Zeitraum: ${format(startDate,'dd.MM.yyyy')} - ${format(days[days.length-1],'dd.MM.yyyy')}</p><table><thead><tr><th>Datum</th><th>Tag</th><th>Stunden</th></tr></thead><tbody>${rows}</tbody></table><p class="sum">Gesamt: ${days.reduce((s,d)=>s+Number(value(iso(d))),0).toFixed(2)} Stunden</p></body></html>`;const win=window.open('','_blank');if(win){win.document.write(html);win.document.close();win.focus();setTimeout(()=>win.print(),250)}}return <section className="panel employee-report"><div className="section-heading"><div><h2>Stundenauswertung</h2><p>Vorausgefüllt aus Einteilungen, Stempelzeiten, Pausen und Abwesenheiten.</p></div><Button variant="outline" disabled={!employeeId} onClick={download}>Als PDF drucken</Button></div><div className="report-controls"><Choice label="Mitarbeiter" value={employeeId} onChange={setEmployeeId} options={employees}/><Choice label="Zeitraum" value={period} onChange={v=>setPeriod(v as 'week'|'month')} options={[{id:'week',name:'Woche'},{id:'month',name:'Monat'}]}/><Input type="date" value={anchor} onChange={e=>setAnchor(e.target.value)}/></div>{!employeeId?<p className="no-docs">Mitarbeiter auswählen, um die Stundenübersicht zu öffnen.</p>:<div className="report-table"><table><thead><tr><th>Datum</th><th>Tag</th><th>Stunden manuell editierbar</th></tr></thead><tbody>{days.map(d=><tr key={iso(d)}><td>{format(d,'dd.MM.yyyy')}</td><td>{format(d,'EEEE',{locale:de})}</td><td><Input type="number" min="0" step="0.25" value={value(iso(d))} onChange={e=>setEdits(x=>({...x,[iso(d)]:e.target.value}))}/></td></tr>)}</tbody></table><b className="report-total">Gesamt: {days.reduce((s,d)=>s+Number(value(iso(d))),0).toFixed(2)} Stunden</b></div>}</section>}
function LocationLabel({value}:{value:string|null}){const [label,setLabel]=useState('');useEffect(()=>{if(!value)return;let g:any;try{g=JSON.parse(value)}catch{return}const controller=new AbortController();fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${encodeURIComponent(g.lat)}&lon=${encodeURIComponent(g.lng)}&zoom=18&addressdetails=1`,{headers:{Accept:'application/json'},signal:controller.signal}).then(r=>r.ok?r.json():null).then((x:any)=>{if(x?.display_name)setLabel(x.display_name)}).catch(()=>{});return()=>controller.abort()},[value]);return <>{label||locationText(value)}</>}
function ProjectInfoDialog({data,projectId,assignment,open,onOpenChange,onEdit,onDelete}:{data:Data;projectId:string;assignment:Assignment|null;open:boolean;onOpenChange:(open:boolean)=>void;onEdit:(assignment:Assignment)=>void;onDelete:(id:string)=>void}){const project=data.projects.find(p=>p.id===projectId);if(!project)return null;const canManage=data.me?.accessRole!=='monteur';const customer=data.customers.find(c=>c.id===project.customer_id);const contacts=data.contacts.filter(c=>c.customer_id===project.customer_id);const foreman=data.resources.find(r=>r.id===project.foreman_id);const assigned=data.resources.filter(r=>data.assignments.some(a=>a.project_id===project.id&&a.resource_id===r.id));const docs=data.documents.filter(d=>d.project_id===project.id);const mapUrl=project.address?`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(project.address)}`:'';return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="project-info-dialog"><DialogHeader><div className="project-info-title"><div><DialogTitle>{project.name}</DialogTitle><DialogDescription>Projektinformationen und eingesetzte Mannschaft</DialogDescription></div>{assignment&&canManage&&<div className="button-row"><Button variant="outline" size="sm" onClick={()=>onEdit(assignment)}><Pencil/>Eintrag bearbeiten</Button><Button variant="ghost" size="sm" className="remove-assignment" onClick={()=>onDelete(assignment.id)}><Trash2/>Löschen</Button></div>}</div></DialogHeader><div className="project-info-grid"><div className="project-info-main"><div className="info-block"><span className="meta-label">BAUSTELLENADRESSE</span><p><MapPin size={16}/>{project.address||'Keine Adresse hinterlegt'}</p>{mapUrl&&<Button variant="outline" size="sm" asChild><a href={mapUrl} target="_blank" rel="noreferrer"><MapPin size={15}/>Navigation öffnen</a></Button>}</div><div className="info-block"><span className="meta-label">KUNDE</span><b>{customer?.name||'Kein Kunde hinterlegt'}</b><small>{customer?.address||''}</small></div><div className="info-block"><span className="meta-label">PROJEKT-E-MAIL</span>{project.project_email?<a href={'mailto:'+project.project_email}>{project.project_email}</a>:'Keine Adresse hinterlegt'}</div><div className="info-block"><span className="meta-label">DASO-OBERMONTEUR</span><b>{foreman?.name||'Noch nicht zugewiesen'}</b></div><div className="info-block"><span className="meta-label">ANSPRECHPARTNER</span>{!contacts.length?<small>Keine Ansprechpartner hinterlegt.</small>:contacts.map(c=><div className="info-contact" key={c.id}><b>{c.name}</b><small>{c.role||'Kundenkontakt'}</small><span>{c.email||'Keine E-Mail'} · {c.phone||c.mobile||'Keine Telefonnummer'}</span></div>)}</div></div><div className="project-info-side"><div className="info-block"><span className="meta-label">EINGETEILTE MITARBEITER</span>{!assigned.length?<small>Niemand eingeteilt.</small>:<div className="assigned-list">{assigned.map(r=><span key={r.id} className="assigned-person">{initials(r.name)}<b>{r.name}</b><small>{r.kind==='contractor'?'Nachunternehmer':'Mitarbeiter'}</small></span>)}</div>}</div><div className="info-block"><span className="meta-label">PROJEKTDATEIEN</span>{!docs.length?<small>Keine Dateien hinterlegt.</small>:<div className="info-docs">{docs.map(d=><a key={d.id} href={'/api/files?id='+d.id} target="_blank" rel="noreferrer"><Download size={15}/><span>{d.name}<small>{d.category}</small></span></a>)}</div>}</div></div></div></DialogContent></Dialog>}
